parts.CLASSIFICATION:
const DWORD slotBit = (1u << i);
const bool edgeProbe = (g_xinputVirtualEndpointProbed & slotBit) == 0;
const bool reprobeRequested =
    (g_xinputSlotReprobeMask.load(std::memory_order_relaxed) & slotBit) != 0;
const bool unknownBefore = (g_xinputSlotUnknownMask & slotBit) != 0;
// R103: a connected slot can change occupant without an edge.
// Revalidate its identity on the existing discovery/boundary pass.
if (edgeProbe || reprobeRequested || unknownBefore || dirtyDiscovery || boundaryFullScan) {
    const bool backoffActive = !edgeProbe && !reprobeRequested &&
        g_xinputSlotReprobeAt[i] != 0 && probeNow < g_xinputSlotReprobeAt[i];
    if (backoffActive) {
        // 路径暂不可读：保持 Unknown，按有界节拍重查（不逐帧重试）。
    } else if (!ymccOpenXInputAvailable()) {
        ++g_feedbackSlotGeneration[i];
        // OpenXInput 不可用 ⇒ 判为物理（掩码位不置）= 原行为，零回归。
        g_xinputVirtualEndpointProbed |= slotBit;
        g_xinputVirtualEndpointMask &= ~slotBit;
        g_xinputSlotUnknownMask &= ~slotBit;
        g_xinputSlotReprobeAt[i] = 0;
        g_xinputSlotIdentityResolvedEpoch[i] =
            g_xinputSlotIdentityEpoch.load(std::memory_order_acquire);
        g_xinputSlotReprobeMask.fetch_and(~slotBit, std::memory_order_relaxed);
    } else {
        ++g_feedbackSlotGeneration[i];
        const std::wstring slotPath = ymccOpenXInputGetDevicePath(i);
        const XInputSlotIdentity slotIdentity = xinputSlotIdentityVerdict(
            /*openXInputAvailable=*/true, /*pathReadable=*/!slotPath.empty(),
            /*virtualIdentity=*/!slotPath.empty() &&
                hidHideIsVirtualIdentity(W2U(slotPath), {}));
        if (slotIdentity == XInputSlotIdentity::Unknown) {
            // GP-GBRETURN-2：路径读不回 = Unknown，不是 Physical。不置 probed
            // （有界退避后重查）；既不算虚拟也不算物理——物理连接掩码排除
            // Unknown 位 ⇒ 不把未知占用者当成"已恢复的物理源"（错签 sourceReacquired）。
            const bool newlyUnknown = !unknownBefore;
            g_xinputSlotUnknownMask |= slotBit;
            g_xinputVirtualEndpointMask &= ~slotBit;
            g_xinputVirtualEndpointProbed &= ~slotBit;
            g_xinputSlotReprobeAt[i] = probeNow + kXInputSlotReprobeBackoffMs;
            g_xinputSlotIdentityResolvedEpoch[i] = 0;   // 未解析：任何映射代都不算新鲜
            if (newlyUnknown) {
                appendNativeLifecycleLog("gamepad-xinput-slot-identity-unknown", {
                    {"slot", i}, {"reprobeRequested", reprobeRequested},
                    {"backoffMs", kXInputSlotReprobeBackoffMs},
                    {"policy", "unknown-not-physical-not-virtual"}
                });
            }
            g_xinputSlotReprobeMask.fetch_and(~slotBit, std::memory_order_relaxed);
        } else {
            const bool wasVirtual = (g_xinputVirtualEndpointMask & slotBit) != 0;
            const bool wasProbed = (g_xinputVirtualEndpointProbed & slotBit) != 0;
            g_xinputSlotUnknownMask &= ~slotBit;
            g_xinputVirtualEndpointProbed |= slotBit;
            g_xinputSlotReprobeAt[i] = 0;
            g_xinputSlotIdentityResolvedEpoch[i] =
                g_xinputSlotIdentityEpoch.load(std::memory_order_acquire);
            if (slotIdentity == XInputSlotIdentity::Virtual) {
                g_xinputVirtualEndpointMask |= slotBit;
                if (!wasVirtual || unknownBefore || reprobeRequested) {
                    appendNativeLifecycleLog("gamepad-xinput-virtual-endpoint-slot", {
                        {"slot", i}, {"path", W2U(slotPath)},
                        {"reclassified", wasProbed && !wasVirtual},
                        {"identityEpoch", g_xinputSlotIdentityResolvedEpoch[i]},
                        {"policy", "virtual-endpoint-never-a-physical-source"}
                    });
                }
            } else {
                g_xinputVirtualEndpointMask &= ~slotBit;
                if (wasVirtual) {
                    // 映射变更后旧结论被推翻：原虚拟槽现由物理占用者占用
                    // （现场：随映射变动，旧身份被沿用 ⇒ 输入源接错/归还判据失真）。
                    appendNativeLifecycleLog("gamepad-xinput-slot-identity-reclassified", {
                        {"slot", i}, {"path", W2U(slotPath)},
                        {"from", "virtual"}, {"to", "physical"},
                        {"identityEpoch", g_xinputSlotIdentityResolvedEpoch[i]},
                        {"policy", "identity-reverified-after-mapping-change"}
                    });
                }
            }
            g_xinputSlotReprobeMask.fetch_and(~slotBit, std::memory_order_relaxed);
        }
    }
}

parts.TARGET:
struct PhysicalFeedbackTarget {
    bool msi=false;
    DWORD slot=4;
    unsigned identityEpoch=0;
    unsigned long long sourceGeneration=0,powerGeneration=0,msiModeGeneration=0;
    unsigned sourceTopology=0;
    std::shared_ptr<const HidHideMsiMainSourceRecord> record;
};

parts.METHODS:
static DWORD xinputNonVirtualConnectedMask() {
    return g_xinputConnectedMask & ~g_xinputVirtualEndpointMask;
}
static DWORD xinputPhysicalConnectedMask() {
    // GP-GBRETURN-2：Unknown（路径读不回）不是物理——不并入物理域（旧行为=空路径永久按物理）。
    return xinputNonVirtualConnectedMask() & ~g_xinputSlotUnknownMask;
}
static XInputSlotIdentity xinputSlotIdentityVerdict(bool openXInputAvailable, bool pathReadable,
                                                    bool virtualIdentity) {
    if (!openXInputAvailable) return XInputSlotIdentity::Physical;
    if (!pathReadable) return XInputSlotIdentity::Unknown;
    return virtualIdentity ? XInputSlotIdentity::Virtual : XInputSlotIdentity::Physical;
}
static inline void xinputSlotsMarkDiscoveryDirty() {
    g_xinputDiscoveryDirty.store(true, std::memory_order_relaxed);
    g_xinputTopologyEpoch.fetch_add(1, std::memory_order_acq_rel);
    if (tickCostEnabled()) g_xinputDiscoveryDirtyTick.store(GetTickCount64(), std::memory_order_relaxed);
}
static void xinputSlotsRequestIdentityReprobe(DWORD slots, const char* why) {
    slots &= 0xFu;
    if (slots == 0) return;
    g_xinputSlotReprobeMask.fetch_or(slots, std::memory_order_acq_rel);
    const unsigned epoch = g_xinputSlotIdentityEpoch.fetch_add(1, std::memory_order_acq_rel) + 1;
    appendNativeLifecycleLog("gamepad-xinput-slot-identity-reprobe", {
        {"slots", slots}, {"why", why ? why : "mapping-change"},
        {"identityEpoch", epoch},
        {"policy", "mapping-change-invalidates-slot-identity"}
    });
}
static std::string hidHideUpper(std::string value) {
    for (char& c : value) c = static_cast<char>(toupper(static_cast<unsigned char>(c)));
    return value;
}
static bool hidHideIsVirtualIdentity(const std::string& deviceInstanceId, const std::string& base) {
    const std::string joined = hidHideUpper(deviceInstanceId + "|" + base);
    return joined.find("HIDMAESTRO") != std::string::npos ||
        joined.find("HM-CTL") != std::string::npos ||
        joined.find("VIGEM") != std::string::npos;
}

parts.CURRENT:
static bool physicalFeedbackSlotCurrent(const PhysicalFeedbackTarget& target) {
    const DWORD allowed=xinputPhysicalConnectedMask() & (g_xinputPhysicalSourceLocked?g_xinputPhysicalSourceMask:0xFu);
    return target.slot<4 && (allowed&(1u<<target.slot)) &&
        !(g_xinputSlotReprobeMask.load(std::memory_order_acquire)&(1u<<target.slot)) &&
        target.identityEpoch==g_xinputSlotIdentityEpoch.load(std::memory_order_acquire) &&
        target.identityEpoch==g_xinputSlotIdentityResolvedEpoch[target.slot] &&
        target.sourceGeneration==g_feedbackSlotGeneration[target.slot];
}

parts.STOP:
static void physicalFeedbackStopTarget(const PhysicalFeedbackTarget& target,bool touch=false) {
    if(target.powerGeneration!=currentPowerGeneration() || !hardwareWriteAllowed())return;
    if(target.msi) {
        if(!target.record)return;
        if(target.msiModeGeneration!=g_msiFeedbackModeGeneration.load(std::memory_order_acquire))return;
        const ymcc::touchhaptic::SourceToken token{ymcc::touchhaptic::Backend::Msi,target.record->generation,
            target.msiModeGeneration,target.powerGeneration,4,target.sourceTopology};
        (void)msiDinputFeedbackWrite(0,0,false,"pulse-stop",target.record.get(),touch,&token);
    } else {
        std::lock_guard<std::mutex> sourceLock(g_gamepadReadMx);
        if(physicalFeedbackSlotCurrent(target)) { XINPUT_VIBRATION zero{};(void)g_feedbackSetState(target.slot,&zero); }
    }
}

parts.FINISH:
static void physicalFeedbackFinish(unsigned long long generation) {
    std::lock_guard<std::mutex> lock(g_feedbackPulseMx);
    if(!g_feedbackPulseActive || generation!=g_rogVibratePulseGen)return;
    physicalFeedbackStopTarget(g_feedbackPulseTarget,g_feedbackPulseTouch);g_feedbackPulseActive=false;
}

parts.READY:
static ymcc::touchhaptic::SourceToken nativePhysicalFeedbackReady() {
    using namespace ymcc::touchhaptic;SourceToken token;token.power=currentPowerGeneration();
    if(!hardwareWriteAllowed()||g_exitRequested.load(std::memory_order_acquire))return token;
    const auto msiGeneration=g_msiFeedbackSourceGeneration.load(std::memory_order_acquire);
    if(msiGeneration){
        const auto mode=g_msiFeedbackModeGeneration.load(),topology=(unsigned long long)g_xinputTopologyEpoch.load();
        if(g_msiDinputSourceValid.load(std::memory_order_acquire)&&g_msiFeedbackSamplePower.load()==token.power&&
            g_msiFeedbackSampleMode.load()==mode&&g_msiFeedbackSampleTopology.load()==topology){
            token.backend=Backend::Msi;token.generation=msiGeneration;token.identity=mode;token.topology=topology;
        }
        return token; // A bound but unreadable MSI source never falls through to an arbitrary XInput slot.
    }
    std::lock_guard<std::mutex> sourceLock(g_gamepadReadMx);
    PhysicalFeedbackTarget target;target.slot=g_xinputPrimarySlot;target.identityEpoch=g_xinputSlotIdentityEpoch.load(std::memory_order_acquire);
    if(target.slot<4)target.sourceGeneration=g_feedbackSlotGeneration[target.slot];
    if(physicalFeedbackSlotCurrent(target)){token.backend=Backend::XInput;token.slot=target.slot;
        token.identity=target.identityEpoch;token.generation=target.sourceGeneration;token.topology=g_xinputTopologyEpoch.load();}
    return token;
}

parts.START:
static ymcc::touchhaptic::Receipt nativePhysicalFeedbackStart(int strength,int durationMs,bool touch,
    const ymcc::touchhaptic::SourceToken* expected=nullptr) {
    using namespace ymcc::touchhaptic;Receipt receipt;receipt.strength=std::clamp(strength,0,100);
    receipt.durationMs=std::clamp(durationMs,10,1000);
    std::lock_guard<std::mutex> lock(g_feedbackPulseMx);
    if(!hardwareWriteAllowed()||g_exitRequested.load(std::memory_order_acquire)){
        receipt.reason=Reason::PowerTransition;return receipt;}
    if(touch&&g_feedbackPulseActive&&!g_feedbackPulseTouch){receipt.reason=Reason::ManualPulseActive;return receipt;}
    PhysicalFeedbackTarget target;target.powerGeneration=currentPowerGeneration();
    if(expected&&expected->power!=target.powerGeneration){receipt.reason=Reason::PowerTransition;return receipt;}
    const auto source=msiDinputFeedbackSourceSnapshot();
    if(source){
        const auto& record=*source;
        receipt.backend=Backend::Msi;receipt.managed=true;
        if(expected&&(expected->backend!=Backend::Msi||expected->generation!=record.generation||expected->identity!=g_msiFeedbackModeGeneration.load())){
            receipt.reason=Reason::SourceChanged;return receipt;}
        target.msi=true;target.record=source;target.msiModeGeneration=expected?expected->identity:g_msiFeedbackModeGeneration.load();
        target.sourceTopology=expected?(unsigned)expected->topology:g_xinputTopologyEpoch.load();
        if(touch&&(!g_msiDinputSourceValid.load(std::memory_order_acquire)||g_msiFeedbackSamplePower.load()!=target.powerGeneration||
            g_msiFeedbackSampleMode.load()!=target.msiModeGeneration||g_msiFeedbackSampleTopology.load()!=target.sourceTopology)){
            receipt.reason=Reason::SourcePending;return receipt;}
        if(g_feedbackPulseActive&&!g_feedbackPulseTarget.msi)physicalFeedbackStopTarget(g_feedbackPulseTarget,g_feedbackPulseTouch);
        const bool a1m=g_machineIdentity.deviceClass=="HandheldCompanion.Devices.ClawA1M";
        receipt.motor=a1m?(receipt.strength>0?193:0):(receipt.strength*255+50)/100;
        const SourceToken token{Backend::Msi,record.generation,target.msiModeGeneration,target.powerGeneration,4,target.sourceTopology};
        const auto fb=msiDinputFeedbackWrite((BYTE)receipt.motor,(BYTE)receipt.motor,a1m,touch?"touch-feedback":"vibrate",&record,touch,&token);
        receipt.ok=fb.ok;receipt.attempted=fb.attempted;receipt.written=fb.written;receipt.error=fb.lastError;
        if(!fb.ok)receipt.reason=fb.reason;
        if(!fb.attempted)return receipt;
    }else{
        std::lock_guard<std::mutex> sourceLock(g_gamepadReadMx);
        target.slot=g_xinputPrimarySlot;target.identityEpoch=g_xinputSlotIdentityEpoch.load(std::memory_order_acquire);
        if(target.slot<4)target.sourceGeneration=g_feedbackSlotGeneration[target.slot];
        receipt.backend=Backend::XInput;receipt.slot=target.slot;
        if(!physicalFeedbackSlotCurrent(target)){receipt.reason=Reason::SourcePending;return receipt;}
        if(expected&&(expected->backend!=Backend::XInput||expected->slot!=target.slot||
            expected->generation!=target.sourceGeneration||expected->identity!=target.identityEpoch||expected->topology!=g_xinputTopologyEpoch.load())){
            receipt.reason=Reason::SourceChanged;return receipt;}
        // Retire the former MSI or physical slot only after leaving the source lock.
        if(g_feedbackPulseActive&&g_feedbackPulseTarget.msi){
            physicalFeedbackStopTarget(g_feedbackPulseTarget,g_feedbackPulseTouch);
        }else if(g_feedbackPulseActive&&g_feedbackPulseTarget.slot!=target.slot&&physicalFeedbackSlotCurrent(g_feedbackPulseTarget)){
            XINPUT_VIBRATION zero{};(void)g_feedbackSetState(g_feedbackPulseTarget.slot,&zero);
        }
        const WORD level=(WORD)((DWORD)receipt.strength*65535u/100u);XINPUT_VIBRATION pulse{level,level};
        const DWORD rc=g_feedbackSetState(target.slot,&pulse);receipt.ok=rc==ERROR_SUCCESS;receipt.attempted=true;
        receipt.error=rc;receipt.motor=level;if(!receipt.ok)receipt.reason=Reason::WriteFailed;
        if(!touch)appendNativeLifecycleLog("gamepad-vibrate",{{"slot",target.slot},{"connectedMask",g_xinputConnectedMask},
            {"admittedMask",g_xinputAdmittedMask},{"primarySlot",g_xinputPrimarySlot},{"strength",receipt.strength},
            {"level",level},{"durationMs",receipt.durationMs},{"touchFeedback",touch},{"rc",rc},{"ok",receipt.ok}});
    }
    g_feedbackPulseTarget=target;g_feedbackPulseActive=true;g_feedbackPulseTouch=touch;
    receipt.pulseGeneration=++g_rogVibratePulseGen;return receipt;
}

parts.SCHEDULE:
static bool gamepadSerialScheduleFeedbackStop(unsigned long long generation,int durationMs) {
    std::lock_guard<std::mutex> lock(g_gamepadSerialMx);
    if(g_gamepadSerialStopping||g_exitRequested.load(std::memory_order_acquire))return false;
    gamepadSerialStartLocked();g_gamepadSerialFeedbackStop=FeedbackStopDeadline{generation,GetTickCount64()+(unsigned)durationMs};
    g_gamepadSerialCv.notify_one();return true;
}

