g_xinputKnownSlotMask &= ~(1u << i);
xinputSlotsMarkDiscoveryDirty();
// 批113：槽号复用/重枚举必须重新解析身份（与"不继承旧准入"同一条纪律）。
g_xinputVirtualEndpointProbed &= ~(1u << i);
g_xinputVirtualEndpointMask &= ~(1u << i);
// GP-GBRETURN-2：Unknown/重查节拍/解析代随掉线一并复位（槽号复用一切重来）。
g_xinputSlotUnknownMask &= ~(1u << i);
g_xinputSlotReprobeAt[i] = 0;
g_xinputSlotIdentityResolvedEpoch[i] = 0;

